    'Review admissions, student profiles, and recent enrollments.':
        'प्रवेश, छात्र प्रोफ़ाइल और हाल के नामांकन की समीक्षा करें।',
    'Review and maintain your platform-level account details.':
        'अपने प्लेटफ़ॉर्म-स्तरीय खाता विवरण की समीक्षा करें और उसे बनाए रखें।',
    'Review and manage the weekly teaching plan class-wise and section-wise.':
        'कक्षा - वार और अनुभाग - वार साप्ताहिक शिक्षण योजना की समीक्षा और प्रबंधन करें।',
    'Review and update staff leave approvals.':
        'कर्मचारियों की छुट्टियों की स्वीकृतियों की समीक्षा करें और उन्हें अद्यतन करें।',
    'Review assigned homework, submit your work, and track marks.':
        'असाइन किए गए होमवर्क की समीक्षा करें, अपना काम सबमिट करें और निशान ट्रैक करें।',
    'Review borrowers class-section wise, generate library card numbers for students, and track fines or overdue items.':
        'कक्षा-अनुभाग के अनुसार उधारकर्ताओं की समीक्षा करें, छात्रों के लिए लाइब्रेरी कार्ड नंबर तैयार करें, और जुर्माना या अतिदेय वस्तुओं पर नज़र रखें।',
    'Review campaign progress and teacher-wise feedback results in one place.':
        'एक ही स्थान पर अभियान की प्रगति और शिक्षक-वार फीडबैक परिणामों की समीक्षा करें।',
    'Review every complaint you have submitted and its latest progress.':
        'आपके द्वारा सबमिट की गई प्रत्येक शिकायत और उसकी नवीनतम प्रगति की समीक्षा करें।',
    'Review hostel fee and payment collection details for {selectedHostelFee.studentName}.':
        '{selectedHostelFee.studentName} के लिए हॉस्टल शुल्क और भुगतान संग्रह विवरण की समीक्षा करें।',
    'Review hostel fee details.': 'हॉस्टल के शुल्क के ब्यौरे पर गौर करें।',
    'Review income entries saved for the current academic session.':
        'वर्तमान शैक्षणिक सत्र के लिए सहेजी गई आय प्रविष्टियों की समीक्षा करें।',
    'Review new book requests and estimate upcoming procurement spend.':
        'नई पुस्तक अनुरोधों की समीक्षा करें और आगामी खरीद व्यय का अनुमान लगाएं।',
    'Review paid and pending fee records.': 'भुगतान किए गए और बकाया शुल्क के रिकॉर्ड की समीक्षा करें।',
    'Review public website requests and enroll them directly into student records.':
        'सार्वजनिक वेबसाइट अनुरोधों की समीक्षा करें और उन्हें सीधे छात्र रिकॉर्ड में दर्ज करें।',
    'Review schedules, assigned class sections, question counts, and submissions.':
        'शेड्यूल, निर्दिष्ट कक्षा अनुभाग, प्रश्नों की संख्या और सबमिशन की समीक्षा करें।',
    'Review staff member information in a read-only view.':
        'स्टाफ सदस्यों की जानकारी की समीक्षा केवल पढ़ने योग्य दृश्य में करें।',
    'Review subscription dates to identify schools that may need follow-up soon.':
        'उन स्कूलों की पहचान करने के लिए सदस्यता तिथियों की समीक्षा करें जिन्हें जल्द ही अनुवर्ती कार्रवाई की आवश्यकता हो सकती है।',
    'Review the captured details for this enquiry.': 'इस पूछताछ के लिए प्राप्त विवरण की समीक्षा करें।',
    'Review the full communication record and recipient summary.':
        'संपूर्ण संचार रिकॉर्ड और प्राप्तकर्ता सारांश की समीक्षा करें।',
    'Review the full exam paper, including answer choices and the saved correct answer.':
        'उत्तर विकल्पों और सहेजे गए सही उत्तर सहित संपूर्ण परीक्षा पेपर की समीक्षा करें।',
    'Review the latest background CSV import jobs from this screen.':
        'इस स्क्रीन से नवीनतम पृष्ठभूमि CSV आयात नौकरियों की समीक्षा करें।',
    'Review the recorded complaint information.': 'दर्ज की गई शिकायत जानकारी की समीक्षा करें।',
    'Review the recorded dispatch information.': 'दर्ज की गई प्रेषण जानकारी की समीक्षा करें।',
    'Review the recorded incoming delivery information.': 'दर्ज की गई आने वाली डिलीवरी जानकारी की समीक्षा करें।',
    'Review the recorded information for this phone call.': 'इस फ़ोन कॉल के लिए रिकॉर्ड की गई जानकारी की समीक्षा करें.',
